<?php require __DIR__.'/../config.php';$cat=trim($_GET['category']??'');$cats=db()->query('SELECT * FROM categories ORDER BY name')->fetchAll();if($cat){$st=db()->prepare("SELECT p.*,c.name category_name FROM posts p LEFT JOIN categories c ON c.id=p.category_id WHERE p.status='published' AND c.slug=? ORDER BY COALESCE(p.published_at,p.created_at) DESC");$st->execute([$cat]);$posts=$st->fetchAll();}else{$posts=db()->query("SELECT p.*,c.name category_name FROM posts p LEFT JOIN categories c ON c.id=p.category_id WHERE p.status='published' ORDER BY COALESCE(p.published_at,p.created_at) DESC")->fetchAll();}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Blog — <?=e(setting('site_name'))?></title><meta name="description" content="Articles by <?=e(setting('site_name'))?>"><link rel="stylesheet" href="../assets/style.css"></head><body><header class="nav"><a class="logo" href="../">SK<span>.</span></a><nav><a href="../#work">Work</a><a href="../#skills">Skills</a><a href="./">Blog</a><a href="../#about">About</a><a href="../#contact">Contact</a></nav><a class="nav-cta" href="../#contact">Let's talk ↗</a></header><main class="section" style="padding-top:150px"><span class="label">BLOG / ARTICLES</span><h1 style="font-size:clamp(55px,9vw,110px);letter-spacing:-7px;line-height:.9">Ideas,<br><em>notes & builds.</em></h1><div class="actions" style="margin:35px 0"><?php foreach($cats as $c):?><a class="btn ghost" href="?category=<?=e($c['slug'])?>"><?=e($c['name'])?></a><?php endforeach;?></div><div class="post-grid"><?php foreach($posts as $p):?><a class="post-card" href="post.php?slug=<?=e($p['slug'])?>"><div class="post-image" style="background-image:url('../<?=e($p['image_url']??'')?>')"></div><small><?=e($p['category_name']?:'Article')?></small><h3><?=e($p['title'])?></h3><p><?=e($p['excerpt'])?></p><span>Read article ↗</span></a><?php endforeach;?><?php if(!$posts):?><div class="empty">No published posts in this category.</div><?php endif;?></div></main></body></html>
